import json
BP={"refPath":"/Game/Gameplay/UI/V2/WBP_UIRoot.WBP_UIRoot"}
U="UMGToolSet.UMGToolSet.";O="editor_toolset.toolsets.object.ObjectTools."
def call(name,params):return execute_tool(name,json.dumps(params))["returnValue"]
def tree():return call(U+"GetWidgets",{"widgetBlueprint":BP})
def add(cls,name,parent):return call(U+"AddWidget",{"widgetBlueprint":BP,"widgetClass":{"refPath":cls},"widgetDisplayName":name,"parentWidget":parent,"childIndex":-1})
def update(obj,desired):
    schema=json.loads(call(O+"list_properties",{"instance":obj}))
    values={}
    for wanted,value in desired.items():
        key=next((k for k in schema if k.lower().replace("_","")==wanted.lower().replace("_","")),None)
        assert key,(wanted,list(schema));values[key]=value
        if wanted.endswith("DesiredHeight") or wanted.endswith("DesiredWidth"):
            flag=next((k for k in schema if k.lower().replace("_","")==("bOverride"+wanted).lower()),None)
            if flag:values[flag]=True
    call(O+"get_properties",{"instance":obj,"properties":list(values)})
    assert call(O+"set_properties",{"instance":obj,"values":json.dumps(values)})
def run():
    d={w["widgetName"]:w for w in tree()["widgets"]};created=[]
    for page,host,frame,view,cls in [
      ("Screen_Wardrobe","WardrobeViewport","WardrobeViewportFrame","UnifiedWardrobe","/Game/Gameplay/UI/V2/WBP_UIWardrobe.WBP_UIWardrobe_C"),
      ("Screen_Boosters","ShopViewport","ShopViewportFrame","UnifiedShop","/Game/Gameplay/UI/V2/WBP_UIShop.WBP_UIShop_C")]:
        assert page in d
        if host not in d:d[host]=add("/Script/UMG.ScrollBox",host,d[page]["widget"]);created.append(host)
        if frame not in d:d[frame]=add("/Script/UMG.SizeBox",frame,d[host]["widget"]);created.append(frame)
        across=host+"Horizontal";width=host+"Content"
        if across not in d:d[across]=add("/Script/UMG.ScrollBox",across,d[frame]["widget"]);created.append(across)
        if width not in d:d[width]=add("/Script/UMG.SizeBox",width,d[across]["widget"]);created.append(width)
        if view not in d:d[view]=add(cls,view,d[width]["widget"]);created.append(view)
        update(d[across]["widget"],{"orientation":"Orient_Horizontal","scrollBarVisibility":"Collapsed","scrollWhenFocusChanges":"InstantScroll"})
        update(d[width]["widget"],{"minDesiredWidth":1856})
        update(d[host]["widget"],{"scrollBarVisibility":"Collapsed","scrollWhenFocusChanges":"InstantScroll"})
        update(d[host]["slot"],{"layoutData":{"offsets":{"left":32,"top":32,"right":32,"bottom":32},"anchors":{"minimum":{"x":0,"y":0},"maximum":{"x":1,"y":1}},"alignment":{"x":0,"y":0}},"bAutoSize":False})
        update(d[frame]["widget"],{"minDesiredHeight":1016})
        update(d[frame]["slot"],{"horizontalAlignment":"HAlign_Fill"})
        update(d[view]["slot"],{"horizontalAlignment":"HAlign_Left","verticalAlignment":"VAlign_Center"})
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":BP})
    assert call("editor_toolset.toolsets.asset.AssetTools.save_assets",{"asset_paths":["/Game/Gameplay/UI/V2/WBP_UIRoot"]})
    return {"saved":True,"created":created,"info":tree()["info"]}
